% LU factorization method for solving linear equations
% 3 equations are: 2x1 - 3x2 + x3 = 7; x1 - x2 - 2x3 = -2; 3x1 + x2 - x3 = 0

% Define the coefficients matrix A and constants vector b
A = [2 -3 1; 1 -1 -2; 3 1 -1];
b = [7; -2; 0];

% Step 1: LU factorization
[L, U, P] = lu(A); % find the LU factorization of A

% Step 2: Solve Ly = Pb for y using forward substitution
y = forward_substitution(L, P*b);

% Step 3: Solve Ux = y for x using back substitution
x = back_substitution(U, y);

% Display the solution
fprintf('The solution is: x1 = %.2f, x2 = %.2f, x3 = %.2f\n', x(1), x(2), x(3));

% Plot the solution as a 3D point
plot3(x(1), x(2), x(3), 'ro', 'MarkerSize', 10, 'MarkerFaceColor', 'r');
xlabel('x1');
ylabel('x2');
zlabel('x3');
title('Solution using LU factorization method');
grid on;

% Functions for forward and back substitution
function y = forward_substitution(L, b)
n = size(L, 1);
y = zeros(n, 1);
for i = 1 : n % solve each equation for corresponding variable
    y(i) = (b(i) - L(i, 1:i-1) * y(1:i-1)) / L(i, i);
end
end

function x = back_substitution(U, y)
n = size(U, 1);
x = zeros(n, 1);
for i = n : -1 : 1 % solve each equation for corresponding variable
    x(i) = (y(i) - U(i, i+1:n) * x(i+1:n)) / U(i, i);
end
end

